style.css:
@-moz-document domain("google.com") {
/* Main background */
  body {
    background: url("https://i.pinimg.com/736x/00/b0/c0/00b0c0112964c29b6fd154526e7d8d24.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Optional: make search box more visible */
  input[type="text"] {
    background-color: rgba(255, 255, 255, 0.6) !important;
    color: #000 !important;
    border-radius: 20px !important;
    padding: 10px 15px !important;
    border: none !important;
  }

  /* Optional: hide footer and extra clutter */
  #footer, #hptl {
    display: none !important;
  }

  /* Optional: invert Google logo for dark backgrounds */
  #logo img {
    filter: brightness(0) invert(1) !important;
  }
}
